import React, { useState, useRef, useEffect } from "react";
import { attendanceAPI } from "./api_service";

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const intervalRef = useRef(null);
  const canvasRef = useRef(null);
  const isProcessingRef = useRef(false);

  const [cameraActive, setCameraActive] = useState(false);
  const [autoMode, setAutoMode] = useState(true);
  const [frameCount, setFrameCount] = useState(0);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);

  // ===================== CAMERA START =====================
  const startCamera = async () => {
    try {
      setError(null);

      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: "user",
          width: { ideal: 1280 },
          height: { ideal: 720 },
        },
        audio: false,
      });

      streamRef.current = stream;

      const video = videoRef.current;
      if (!video) {
        console.error("❌ videoRef not found");
        return;
      }

      video.srcObject = stream;

      await video.play(); // 🔥 CRITICAL FIX

      setCameraActive(true);
      setAutoMode(true);

      startLoop();

      addNotification?.("✅ Caméra activée", "success");
      console.log("🎥 Camera ready");
    } catch (err) {
      console.error("Camera error:", err);
      setError("Impossible d'accéder à la caméra");
    }
  };

  // ===================== LOOP SIMPLE (ROBUSTE) =====================
  const startLoop = () => {
    if (intervalRef.current) return;

    intervalRef.current = setInterval(async () => {
      if (!autoMode) return;
      if (!videoRef.current || isProcessingRef.current) return;

      const video = videoRef.current;

      if (video.readyState < 2) return;

      try {
        isProcessingRef.current = true;

        const canvas = canvasRef.current;
        const ctx = canvas.getContext("2d");

        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;

        ctx.drawImage(video, 0, 0);

        const imageBase64 = canvas.toDataURL("image/jpeg", 0.85);

        setFrameCount((p) => p + 1);

        const response = await attendanceAPI.recognize(imageBase64);
        const data = response?.data;

        console.log("📡 backend:", data);

        if (data?.success && data?.student) {
          setResult({
            success: true,
            name: data.student,
            confidence: (data.confidence * 100).toFixed(1),
            time: new Date().toLocaleTimeString(),
          });

          addNotification?.(`✅ ${data.student}`, "success");

          // pause courte après succès
          setAutoMode(false);
          setTimeout(() => setAutoMode(true), 2500);
        } else {
          setResult({
            success: false,
            message: "Non reconnu",
            time: new Date().toLocaleTimeString(),
          });
        }
      } catch (err) {
        console.warn("frame error:", err.message);
      } finally {
        isProcessingRef.current = false;
      }
    }, 700); // 🔥 sweet spot (ni trop rapide ni lent)
  };

  // ===================== STOP =====================
  const stopCamera = () => {
    if (intervalRef.current) clearInterval(intervalRef.current);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
    }

    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }

    setCameraActive(false);
    setAutoMode(false);
  };

  // ===================== MANUAL =====================
  const captureOnce = async () => {
    if (!videoRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");

    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;

    ctx.drawImage(videoRef.current, 0, 0);

    const imageBase64 = canvas.toDataURL("image/jpeg");

    const response = await attendanceAPI.recognize(imageBase64);
    setResult(response?.data);
  };

  useEffect(() => {
    return () => stopCamera();
  }, []);

  // ===================== UI =====================
  return (
    <div style={{ padding: 20 }}>
      <h2>🎥 Camera Hybrid Stable</h2>

      <div style={{ position: "relative" }}>
        <video
          ref={videoRef}
          autoPlay
          muted
          playsInline
          style={{
            width: "100%",
            borderRadius: 12,
            background: "#000",
          }}
        />
      </div>

      <div style={{ marginTop: 10 }}>
        {!cameraActive ? (
          <button onClick={startCamera}>▶️ Start Camera</button>
        ) : (
          <>
            <button onClick={captureOnce}>📸 Scan</button>
            <button onClick={() => setAutoMode(!autoMode)}>
              {autoMode ? "⏸ Pause" : "▶️ Resume"}
            </button>
            <button onClick={stopCamera}>🛑 Stop</button>
          </>
        )}
      </div>

      <p>Frames: {frameCount}</p>

      {result && (
        <div style={{ marginTop: 20 }}>
          {result.success ? (
            <div>✅ {result.name} ({result.confidence}%)</div>
          ) : (
            <div>❌ {result.message}</div>
          )}
        </div>
      )}

      <canvas ref={canvasRef} style={{ display: "none" }} />
    </div>
  );
};

export default CameraRecognition;
